  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "The 18F-labeled H3 radioligand [18F]3 (H3-2406), which shares the amide-fluorophenyl and saturated N-heterocycle motif, showed good brain uptake with SUV 2.4 in rat PET, supporting CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The related 11C-labeled fluorophenyl-pyrimidine piperidine tracer [11C]4 reached 4.1 %ID in cynomolgus monkey brain PET, demonstrating robust BBB penetration for a scaffold with the same fluorophenyl-pyrimidine and piperidine elements.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "The fluorophenyl piperidine radiotracer [18F]/[11C]BMP showed extremely high brain uptake (>14 %ID/g) in mice, supporting that neutral, low-TPSA fluorophenyl amide/ester piperidines penetrate the BBB well.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Venglustat, a strong CNS penetrant with a fluorophenyl heteroaryl and amide/carbamate motif, reduced brain glycosphingolipids by more than 20%, confirming meaningful CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Peripherally restricted MAGL tracers with a fluorophenyl amide and fluorinated saturated heterocycle showed low brain accumulation, but their higher polarity and peripheral-restriction design limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: multiple direct PET and biodistribution measurements on structurally related neutral, low-TPSA fluorophenyl amide/piperidine tracers show good-to-high brain uptake, and the favorable physicochemical prior outweighs the few poor-penetration analogues with more polar or HBD-containing features.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or PET measurement for the exact query molecule.",
    "Morgan similarities to available evidence are modest (0.26-0.30), limiting quantitative transfer.",
    "No in vitro P-gp/BCRP efflux data for the query; efflux liability is inferred only from physicochemical properties.",
    "Species differences and PET tracer dose/formulation may affect translation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

